const fs=require("fs"),fetch=require("node-fetch"),Jimp=require("jimp");process.chdir(__dirname);const base="https://api.github.com/repos/ajv-validator/ajv/contributors",{GH_TOKEN_PUBLIC:GH_TOKEN_PUBLIC}=process.env,SIZE=64;async function main(){const e=[];let t=1;for(;;){const o=await fetch(`${base}?per_page=100&page=${t++}`,{headers:{Authorization:`token ${GH_TOKEN_PUBLIC}`}}),n=await o.json();if(0===n.length)break;e.push(...n)}const o=["dependabot-preview[bot]","greenkeeper[bot]","greenkeeperio-bot"],n=e.filter(e=>!o.includes(e.login)).sort((e,t)=>t.contributions-e.contributions),r=new Jimp(64*n.length,64);for(let e=0;e<n.length;e+=1){const t=n[e];console.log(`${e+1} / ${n.length}: ${t.login}`);const o=await fetch(t.avatar_url),i=await o.arrayBuffer(),s=await Jimp.read(i);s.resize(64,64),r.composite(s,64*e,0)}await r.quality(80).write("../docs/.vuepress/components/Contributors/contributors.jpg");const i=`[\n\t${n.map(e=>`'${e.login}'`).join(",\n\t")}\n]`;fs.writeFileSync("../docs/.vuepress/components/Contributors/_contributors.js",`export default ${i};`)}main();